package net.karenax.fred;

import android.app.*;
import android.content.*;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.webkit.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.util.concurrent.*;

public final class MainActivity extends Activity {
    private static final int IMPORT=41,EXPORT=42,FILES=43,NOTIFICATION_PERMISSION=44;
    private final ExecutorService io=Executors.newSingleThreadExecutor();
    private WebView web;
    private SecureStore store;
    private LocalVoice voice;
    private volatile LoopbackServer server;
    private ValueCallback<Uri[]> fileCallback;
    private byte[] exportBytes;
    private boolean demo;
    private volatile boolean exitRequested;
    private String permissionIdentity="",pendingNotification="",pendingIdentity="";
    private boolean notificationOpening;
    private android.window.OnBackInvokedCallback backCallback;
    @Override public void onCreate(Bundle saved){super.onCreate(saved);store=new SecureStore(this);try{voice=new LocalVoice(this);}catch(Exception e){throw new IllegalStateException("Paquet vocal absent",e);}demo=BuildConfig.DEBUG&&(getIntent().getBooleanExtra("fred_demo",false)||getIntent().getBooleanExtra("demo",false));if(Build.VERSION.SDK_INT>=30)getWindow().setDecorFitsSystemWindows(false);FrameLayout root=new FrameLayout(this);web=new WebView(this);root.addView(web,new FrameLayout.LayoutParams(-1,-1));setContentView(root);applySafeInsets(root);
        WebView.setWebContentsDebuggingEnabled(BuildConfig.DEBUG);WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(true);settings.setAllowFileAccessFromFileURLs(false);settings.setAllowUniversalAccessFromFileURLs(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setCacheMode(WebSettings.LOAD_NO_CACHE);settings.setMediaPlaybackRequiresUserGesture(true);settings.setSupportMultipleWindows(false);CookieManager.getInstance().setAcceptCookie(false);web.addJavascriptInterface(new AndroidBridge(),"AndroidClient");
        web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){Uri uri=request.getUrl();LoopbackServer current=server;if(current!=null&&uri.toString().equals(current.chatUrl()))return false;if(request.isForMainFrame())openExternal(uri.toString());return true;}@Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){Uri uri=request.getUrl();LoopbackServer current=server;if(current!=null&&"http".equals(uri.getScheme())&&"127.0.0.1".equals(uri.getHost())&&uri.getPort()==current.port())return null;return new WebResourceResponse("text/plain","UTF-8",403,"Forbidden",java.util.Collections.emptyMap(),new ByteArrayInputStream(new byte[0]));}});
        web.setWebChromeClient(new WebChromeClient(){@Override public boolean onShowFileChooser(WebView view,ValueCallback<Uri[]> callback,FileChooserParams params){if(fileCallback!=null)fileCallback.onReceiveValue(null);fileCallback=callback;try{Intent intent=params.createIntent();intent.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(intent,FILES);return true;}catch(ActivityNotFoundException e){fileCallback=null;callback.onReceiveValue(null);toast("Aucun sélecteur de fichiers disponible.");return false;}}});
        web.setDownloadListener((url,userAgent,contentDisposition,mime,length)->toast("Utilisez le bouton Exporter pour enregistrer le document."));
        if(Build.VERSION.SDK_INT>=33){backCallback=this::handleBack;getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,backCallback);}
        captureNotification(getIntent());io.execute(()->{try{JSONObject profile=demo?DemoTransport.profile():store.read("profile");if(profile!=null)Profile.validate(profile);startClient(profile);}catch(Exception e){showError("Démarrage impossible",Remote.safeMessage(e));}});
    }
    private void applySafeInsets(FrameLayout root){
        root.setOnApplyWindowInsetsListener((view,insets)->{
            if(Build.VERSION.SDK_INT>=30){
                // Android 15+ draws edge to edge: the IME is an inset, not a resized root window.
                // The union reserves each edge once, including max(navigation bar, keyboard) below.
                android.graphics.Insets safe=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout()|WindowInsets.Type.ime());
                view.setPadding(safe.left,safe.top,safe.right,safe.bottom);
                return WindowInsets.CONSUMED;
            }
            // Before API 30 the platform's adjustResize behavior remains responsible for the IME.
            view.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());
            return insets;
        });
        root.requestApplyInsets();
    }
    private void startClient(JSONObject profile)throws Exception {if(isFinishing()||isDestroyed())return;LoopbackServer previous=server;if(previous!=null)voice.pause();ClientBackend backend=new ClientBackend(this,store,profile,demo);if(previous!=null){if(!previous.backend.identity.equals(backend.identity))previous.backend.notifications.clear();previous.close();}LoopbackServer next=new LoopbackServer(this,backend);server=next;runOnUiThread(()->{if(!isDestroyed()){web.clearCache(true);web.loadUrl(next.chatUrl());}});}
    private void captureNotification(Intent intent){if(intent==null)return;String id=intent.getStringExtra(NativeNotifications.EXTRA_ID),identity=intent.getStringExtra(NativeNotifications.EXTRA_IDENTITY);if(NativeNotifications.validId(id)&&identity!=null&&identity.length()<128){pendingNotification=id;pendingIdentity=identity;}}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);captureNotification(intent);openPendingNotification();}
    private void openPendingNotification(){runOnUiThread(()->{LoopbackServer current=server;if(current==null||web==null||notificationOpening||pendingNotification.isEmpty())return;if(!current.backend.identity.equals(pendingIdentity)){pendingNotification="";pendingIdentity="";toast("Cette notification appartient à un autre accès personnel.");return;}notificationOpening=true;String id=pendingNotification;web.evaluateJavascript("window.androidNotificationOpened?.("+JSONObject.quote(id)+")||false",value->{notificationOpening=false;if("true".equals(value)&&id.equals(pendingNotification)){pendingNotification="";pendingIdentity="";}});});}
    private void notificationStateChanged(){runOnUiThread(()->{if(web!=null&&!isDestroyed())web.evaluateJavascript("window.androidNotificationPermissionChanged?.()",null);});}
    private void enableNotifications(boolean enabled){runOnUiThread(()->{LoopbackServer current=server;if(current==null||!current.backend.remote.hasProfile()){toast("Importez votre accès personnel.");return;}if(enabled&&Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED){permissionIdentity=current.backend.identity;requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},NOTIFICATION_PERMISSION);return;}io.execute(()->{try{current.backend.notifications.setEnabled(enabled);notificationStateChanged();}catch(Exception e){showError("Notifications indisponibles",Remote.safeMessage(e));}});});}
    @Override public void onRequestPermissionsResult(int requestCode,String[] permissions,int[] grants){super.onRequestPermissionsResult(requestCode,permissions,grants);if(requestCode==LocalVoice.PERMISSION){voice.permissionResult(grants.length>0&&grants[0]==android.content.pm.PackageManager.PERMISSION_GRANTED);return;}if(requestCode!=NOTIFICATION_PERMISSION)return;LoopbackServer current=server;boolean granted=grants.length>0&&grants[0]==android.content.pm.PackageManager.PERMISSION_GRANTED;String requested=permissionIdentity;permissionIdentity="";if(current!=null&&current.backend.identity.equals(requested))io.execute(()->{try{current.backend.notifications.setEnabled(granted);notificationStateChanged();if(!granted)toast("Alertes Android refusées. La boîte de notifications reste disponible dans Fred.");}catch(Exception e){showError("Notifications indisponibles",Remote.safeMessage(e));}});}
    private void showError(String title,String message){runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())new AlertDialog.Builder(this).setTitle(title).setMessage(message).setPositiveButton("OK",null).show();});}
    private void toast(String text){runOnUiThread(()->Toast.makeText(this,text,Toast.LENGTH_LONG).show());}
    private void chooseProfile(){runOnUiThread(()->{LoopbackServer current=server;if(current!=null&&current.backend.remote.active.get()>0){toast("Attendez la fin de la requête avant de changer d’accès.");return;}Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);intent.putExtra(Intent.EXTRA_TITLE,"Choisir un accès Fred (.fred-android, JSON ou EXE personnel)");try{startActivityForResult(intent,IMPORT);}catch(ActivityNotFoundException e){showError("Import impossible","Aucun sélecteur de fichiers disponible.");}});}
    private void openExternal(String url){Uri uri=Uri.parse(url);if(!"https".equals(uri.getScheme())&&!"http".equals(uri.getScheme()))return;runOnUiThread(()->{try{startActivity(new Intent(Intent.ACTION_VIEW,uri));}catch(ActivityNotFoundException e){toast("Aucun navigateur disponible.");}});}
    private void nativeSettings(){runOnUiThread(()->{LoopbackServer current=server;if(current==null)return;String name=current.backend.remote.hasProfile()?Profile.name(current.backend.remote.profile):"Aucun accès importé";new AlertDialog.Builder(this).setTitle("Connexion · "+name).setItems(new String[]{"Connexion HTTPS (Internet)","Connexion WireGuard", "Importer un autre accès personnel"},(dialog,index)->{if(index==2){chooseProfile();return;}io.execute(()->{try{current.backend.selectMode(index==0?"https":"wireguard");runOnUiThread(()->web.evaluateJavascript("window.androidConnectionChanged?.()",null));}catch(Exception e){showError("Connexion impossible",Remote.safeMessage(e));}});}).setNegativeButton("Fermer",null).show();});}
    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode==FILES){if(fileCallback!=null){fileCallback.onReceiveValue(WebChromeClient.FileChooserParams.parseResult(resultCode,data));fileCallback=null;}return;}if(resultCode!=RESULT_OK||data==null||data.getData()==null){if(requestCode==EXPORT)exportBytes=null;return;}Uri uri=data.getData();if(requestCode==IMPORT){io.execute(()->{try{JSONObject profile;try(InputStream input=getContentResolver().openInputStream(uri)){if(input==null)throw new IOException();profile=Profile.importFile(input);}LoopbackServer current=server;if(current!=null&&current.backend.remote.active.get()>0)throw new IllegalArgumentException("Attendez la fin de la requête avant de changer d’accès.");String identity=Profile.identity(profile);JSONObject prefs=store.read(identity+".settings");if(prefs==null)prefs=new JSONObject();prefs.put("connection_selected",false);prefs.remove("endpoint");store.write(identity+".settings",prefs);store.write("profile",profile);demo=false;startClient(profile);toast("Accès personnel importé. Choisissez votre mode de connexion.");}catch(Exception e){showError("Import impossible",e instanceof IllegalArgumentException||e instanceof JSONException?"Profil personnel invalide ou incompatible.":Remote.safeMessage(e));}});}else if(requestCode==EXPORT){byte[] bytes=exportBytes;exportBytes=null;if(bytes==null)return;io.execute(()->{try(OutputStream output=getContentResolver().openOutputStream(uri,"wt")){if(output==null)throw new IOException();output.write(bytes);toast("Fichier enregistré.");}catch(Exception e){showError("Export impossible","Le fichier n’a pas pu être enregistré.");}});}}
    @Override protected void onPause(){if(voice!=null)voice.pause();if(web!=null)web.evaluateJavascript("window.androidFlush?.()",null);super.onPause();}
    private void requestExit(){if(exitRequested||web==null)return;exitRequested=true;web.evaluateJavascript("(async()=>{try{await window.voiceFinishForClose?.();if(typeof busy!=='undefined'&&busy){controller?.abort();try{await api('/v1/cancel',{}, {'X-Qwen-Request':requestId});}catch(e){}while(busy)await new Promise(r=>setTimeout(r,25));}const ok=typeof window.androidFlush==='function'?await window.androidFlush():false;AndroidClient.finishSaved(ok);}catch(e){AndroidClient.finishSaved(false);}})()",null);}
    private void handleBack(){if(web!=null)web.evaluateJavascript("window.androidBack?.()||false",value->{if(!"true".equals(value)&&!exitRequested)new AlertDialog.Builder(this).setTitle("Fermer le client ?").setMessage("La réponse en cours sera interrompue et les conversations seront enregistrées dans la copie locale chiffrée.").setPositiveButton("Fermer",(d,w)->requestExit()).setNegativeButton("Rester",null).show();});else finish();}
    // Android 8–12 still dispatch this legacy method; API 33+ uses the registered platform callback.
    @android.annotation.SuppressLint("GestureBackNavigation")
    @Override public void onBackPressed(){handleBack();}
    @Override protected void onDestroy(){if(voice!=null)voice.close();if(Build.VERSION.SDK_INT>=33&&backCallback!=null)getOnBackInvokedDispatcher().unregisterOnBackInvokedCallback(backCallback);LoopbackServer current=server;server=null;io.execute(()->{if(current!=null)current.close();});io.shutdown();if(fileCallback!=null){fileCallback.onReceiveValue(null);fileCallback=null;}if(web!=null){web.removeJavascriptInterface("AndroidClient");web.destroy();web=null;}super.onDestroy();}
    public final class AndroidBridge {
        @JavascriptInterface public String voiceStatus(){return voice.status();}
        @JavascriptInterface public String voiceAction(String command){return voice.action(command);}
        @JavascriptInterface public String notificationStatus(){LoopbackServer current=server;return current==null?Json.object("enabled",false,"permitted",false).toString():current.backend.notifications.status().toString();}
        @JavascriptInterface public void setNotificationsEnabled(boolean enabled){enableNotifications(enabled);}
        @JavascriptInterface public void notificationInbox(String json){if(json==null||json.length()>1024*1024)return;LoopbackServer current=server;if(current==null||!current.backend.remote.hasProfile())return;io.execute(()->{if(server!=current)return;try{current.backend.notifications.receive(new JSONObject(json));}catch(Exception ignored){/* Inbox stays available if local alert storage or permission fails. */}});}
        @JavascriptInterface public void notificationReady(){openPendingNotification();}
        @JavascriptInterface public void notificationOpened(String id){runOnUiThread(()->{if(id!=null&&id.equals(pendingNotification)){pendingNotification="";pendingIdentity="";}});}
        @JavascriptInterface public void importProfile(){chooseProfile();}
        @JavascriptInterface public void openSettings(){nativeSettings();}
        @JavascriptInterface public String getConnectionInfo(){LoopbackServer current=server;if(current==null)return "{}";return Json.object("profile_required",!current.backend.remote.hasProfile(),"name",current.backend.remote.hasProfile()?Profile.name(current.backend.remote.profile):"","connection",current.backend.remote.state()).toString();}
        @JavascriptInterface public String setConnectionMode(String mode){LoopbackServer current=server;if(current==null)return Json.object("error","Client en cours de démarrage.").toString();try{current.backend.selectMode(mode);runOnUiThread(()->web.evaluateJavascript("window.androidConnectionChanged?.()",null));return Json.object("ok",true).toString();}catch(Exception e){return Json.object("error",Remote.safeMessage(e)).toString();}}
        @JavascriptInterface public void copyText(String text){if(text==null||text.length()>2*1024*1024)return;runOnUiThread(()->{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Fred",text));toast("Texte copié.");});}
        @JavascriptInterface public void openUrl(String url){if(url!=null&&url.length()<4096)openExternal(url);}
        @JavascriptInterface public void finishSaved(boolean saved){if(!exitRequested)return;runOnUiThread(()->{if(!exitRequested||isFinishing()||isDestroyed())return;exitRequested=false;if(saved)finish();else new AlertDialog.Builder(MainActivity.this).setTitle("Enregistrement non confirmé").setMessage("Le client reste ouvert. Réessayez l’enregistrement ou exportez vos conversations pour conserver votre travail.").setPositiveButton("Réessayer",(dialog,which)->requestExit()).setNegativeButton("Rester",null).show();});}
        @JavascriptInterface public synchronized String exportFile(String name,String mime,String base64){if(exportBytes!=null)return Json.object("error","Un export est déjà ouvert.").toString();if(name==null||name.isEmpty()||mime==null||base64==null||base64.length()>23*1024*1024)return Json.object("error","Export trop volumineux ou invalide.").toString();try{byte[] bytes=android.util.Base64.decode(base64,android.util.Base64.DEFAULT);if(bytes.length>16*1024*1024)throw new IllegalArgumentException();String safeName=name.replaceAll("[\\\\/:*?\"<>|\\p{Cntrl}]","_");if(safeName.length()>180)safeName=safeName.substring(0,180);String rawType=mime.split(";",2)[0].trim();String type=rawType.matches("[A-Za-z0-9.+-]+/[A-Za-z0-9.+-]+")?rawType:"application/octet-stream";String suggested=safeName;exportBytes=bytes;runOnUiThread(()->{Intent intent=new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(type).putExtra(Intent.EXTRA_TITLE,suggested);try{startActivityForResult(intent,EXPORT);}catch(ActivityNotFoundException e){exportBytes=null;toast("Aucun sélecteur de fichiers disponible.");}});return Json.object("ok",true,"pending",true).toString();}catch(IllegalArgumentException e){return Json.object("error","Export trop volumineux ou invalide.").toString();}}
    }
}
